import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const userData = localStorage.getItem('currentUser');
    if (userData) setUser(JSON.parse(userData));
    loadSessions();
  }, []);

  const loadSessions = async () => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) return;

      const res = await fetch('http://localhost:8000/api/sessions', {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        setSessions(data);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate('/auth', { replace: true });
  };

  const startSession = (tutorId, subject) => {
    const roomId = `room_${Date.now()}`;
    navigate(`/video/${roomId}`, {
      state: { tutorId, subject, resuming: false },
      replace: true,
    });
  };

  const resumeSession = (session) => {
    navigate(`/video/${session.session_id}`, {
      state: {
        tutorId: session.tutor_id,
        subject: session.subject,
        resuming: true,
      },
      replace: true,
    });
  };

  const lastSession = sessions[0];

  return (
    <div className="min-h-screen bg-slate-950 text-white">
      {/* Header */}
      <header className="border-b border-slate-800">
        <div className="max-w-6xl mx-auto px-6 py-6 flex justify-between items-center">
          <h1 className="text-xl font-semibold">Saarthi</h1>
          <div className="flex items-center gap-6">
            <span className="text-sm text-gray-400">{user?.name}</span>
            <button
              onClick={handleLogout}
              className="text-sm text-gray-400 hover:text-white transition"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-14 space-y-16">
        {/* Resume Section */}
        {lastSession && (
          <section className="bg-slate-900 border border-slate-800 rounded-2xl p-8">
            <p className="text-sm text-gray-400 mb-2">Continue where you left off</p>
            <h2 className="text-2xl font-semibold mb-4">
              {lastSession.subject}
            </h2>
            <button
              onClick={() => resumeSession(lastSession)}
              className="px-6 py-3 bg-indigo-600 hover:bg-indigo-700 rounded-lg font-medium"
            >
              Resume Session
            </button>
          </section>
        )}

        {/* Start New */}
        <section>
          <h3 className="text-lg font-semibold mb-6">Start a new session</h3>
          <div className="grid md:grid-cols-2 gap-6">
            <div className="border border-slate-800 rounded-xl p-6 bg-slate-900">
              <h4 className="text-xl font-medium mb-1">Omkar</h4>
              <p className="text-sm text-gray-400 mb-4">AI & Machine Learning</p>
              <button
                onClick={() => startSession('omkar_ai', 'AI & ML')}
                className="text-sm text-indigo-400 hover:text-indigo-300"
              >
                Start →
              </button>
            </div>

            <div className="border border-slate-800 rounded-xl p-6 bg-slate-900">
              <h4 className="text-xl font-medium mb-1">Priya</h4>
              <p className="text-sm text-gray-400 mb-4">Biology</p>
              <button
                onClick={() => startSession('priya_biology', 'Biology')}
                className="text-sm text-indigo-400 hover:text-indigo-300"
              >
                Start →
              </button>
            </div>
          </div>
        </section>

        {/* History */}
        <section>
          <h3 className="text-lg font-semibold mb-6">Previous sessions</h3>

          {loading ? (
            <p className="text-gray-500">Loading sessions…</p>
          ) : sessions.length === 0 ? (
            <p className="text-gray-500">No sessions yet.</p>
          ) : (
            <div className="space-y-3">
              {sessions.map((s) => (
                <div
                  key={s.session_id}
                  className="flex justify-between items-center border border-slate-800 rounded-lg px-5 py-4 bg-slate-900"
                >
                  <div>
                    <p className="font-medium">
                      {s.subject}
                    </p>
                    <p className="text-xs text-gray-500">
                      {new Date(s.created_at).toLocaleDateString()}
                    </p>
                  </div>
                  <button
                    onClick={() => resumeSession(s)}
                    className="text-sm text-indigo-400 hover:text-indigo-300"
                  >
                    Resume
                  </button>
                </div>
              ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}
